package main

import (
	"bytes"
	"encoding/binary"
	"encoding/hex"
	"fmt"
)

func DomainMask(index, domain int) uint32 {
    if domain < index || domain >= index+32 {
        return 0
    }

    offset := uint(domain - index)
    return 1 << (31 - offset)
}


// build inner TLV: [type][id][data]
func buildTLV(t uint16, id uint32, data []byte) []byte {
	buf := new(bytes.Buffer)
	_ = binary.Write(buf, binary.BigEndian, t)
	_ = binary.Write(buf, binary.BigEndian, id)
	buf.Write(data)
	return buf.Bytes()
}

// ASN.1 length encoding (simple form)
func encLen(l int) []byte {
	if l < 128 {
		return []byte{byte(l)}
	}
	// simplified long form
	b := []byte{byte(0x80 | 4)}
	tmp := make([]byte, 4)
	binary.BigEndian.PutUint32(tmp, uint32(l))
	return append(b, tmp...)
}

// wrap OCTET STRING
func octetString(data []byte) []byte {
	return append(append([]byte{0x04}, encLen(len(data))...), data...)
}

// wrap SEQUENCE
func sequence(items [][]byte) []byte {
	var body bytes.Buffer
	for _, i := range items {
		body.Write(i)
	}
	return append(append([]byte{0x30}, encLen(body.Len())...), body.Bytes()...)
}

func main() {
	hexCerts4 := []string{
"",
}

	hexCerts := []string{
		"",
	}

	hexCerts2 := []string{
"",
}

	hexCerts3 := []string{
"",
}

	var certs,certs2,certs3,certs4 bytes.Buffer

	for _, h := range hexCerts {
		b, _ := hex.DecodeString(h)
		certs.Write(b)
	}
	for _, h := range hexCerts2 {
		b, _ := hex.DecodeString(h)
		certs2.Write(b)
	}
	for _, h := range hexCerts3 {
		b, _ := hex.DecodeString(h)
		certs3.Write(b)
	}
	for _, h := range hexCerts4 {
		b, _ := hex.DecodeString(h)
		certs4.Write(b)
	}

	// x001C = number of KPHs
	x001C := octetString(buildTLV(0x001C, 0x00000001, []byte{}))

	// x001D = certs
	x001D := octetString(buildTLV(0x001D, 0x00000000, certs4.Bytes()))
//	x001D_2 := octetString(buildTLV(0x001D, 0x00000001, certs.Bytes()))
        x0003 := octetString(buildTLV(0x0003, DomainMask(10,16), []byte{}))
        x001F := octetString(buildTLV(0x001F, 0x00000008, []byte{}))
	
	// full module state SEQUENCE
	out := sequence([][]byte{
		x001C,
		x0003,
		x001D,
//		x001D_2,
		x001F,
	})

	fmt.Printf("%x\n", out)
}
